layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="nav"] a { color: color-mix(in srgb, var(--ryt-text) 48%, transparent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12.16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.9728px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 48%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 2px; padding-bottom: 0px; padding-left: 2px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgba(255, 255, 255, 0.02); border-top: 1px solid rgba(255, 255, 255, 0.1); border-right: 1px solid rgba(255, 255, 255, 0.1); border-bottom: 1px solid rgba(255, 255, 255, 0.1); border-left: 1px solid rgba(255, 255, 255, 0.1); border-radius: 999px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 18px; padding-bottom: 0px; padding-left: 18px; transition: transform 0.18s, border-color 0.18s, background 0.18s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: radial-gradient(circle at 18% 14%, rgba(255, 87, 87, 0.08), rgba(0, 0, 0, 0) 24%), radial-gradient(circle at 82% 20%, rgba(141, 87, 255, 0.08), rgba(0, 0, 0, 0) 26%), linear-gradient(rgb(10, 10, 16), rgb(8, 8, 12)); background-size: auto, auto, auto; background-position: 0% 0%, 0% 0%, 0% 0%; background-repeat: repeat, repeat, repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.48px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: fill 0.18s, stroke 0.18s, opacity 0.18s, transform 0.18s }
[data-ryt="button"]:hover { transform: translateY(-1px) }
[data-ryt="nav"] a:hover { color: #f3f0ea }
